#include <vector>

using namespace std;

class Solution {
public:
    int hIndex(vector<int>& citations) {
        int l = 0, r = citations.size(), n = r;
        while (l < r) {
            int m = (l + r) / 2;
            if (citations[m] >= n - m)
                r = m;
            else
                l = m + 1;
        }
        return n - l;
    }
};
